-- CAB-0005: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0005: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'CAB-0005: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('saifuddin-nasution-ismail','mohamed-khaled-nordin') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0005: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kota tinggi') and slug not in ('saifuddin-nasution-ismail','mohamed-khaled-nordin')) then raise exception 'CAB-0005: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0005:%' and (m.source_type <> 'editorial' or e.slug not in ('saifuddin-nasution-ismail','mohamed-khaled-nordin') or m.import_key not like 'CAB-0005:' || e.slug || ':%')) then raise exception 'CAB-0005: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'saifuddin-nasution-ismail','Saifuddin Nasution Ismail','government','Minister of Home Affairs',null,null,'Saifuddin Nasution Ismail is Minister of Home Affairs. He serves as a senator appointed by the Yang di-Pertuan Agong. He is a member of Parti Keadilan Rakyat (PKR).','https://www.moha.gov.my/','/portraits/saifuddin-nasution-ismail.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/Saifuddin1.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Dewan Negara", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dn&id=4033"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'mohamed-khaled-nordin','Mohamed Khaled Nordin','government','Minister of Defence','Kota Tinggi','Johor','Mohamed Khaled Nordin is Minister of Defence. He represents Kota Tinggi, Johor, in the Dewan Rakyat. He is a member of UMNO.','https://www.mod.gov.my/','/portraits/mohamed-khaled-nordin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P156.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Kota Tinggi", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4195"}, {"label": "UMNO · 2023–2026 supreme council", "url": "https://umno-online.my/wp-content/uploads/2026/01/Senarai-MKT-2023-2026-update-Januari-2026-jan-2026-final.pdf"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('saifuddin-nasution-ismail','mohamed-khaled-nordin') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0005: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0005:saifuddin-nasution-ismail:myniise-rollout-2026','Roll out MyNIISe fully in September 2026','Digital',null,null,'2026-09-30','2026-05-04','https://bernama.com/tv/news.php?id=2552525',null,null,'Saifuddin announced full implementation of MyNIISe in September 2026 as part of immigration-system reforms.','The announcement describes preparations and data migration. Full national rollout against this specific September commitment was not established in the reviewed evidence. Status and completion remain unknown; earlier component or project percentages are not substituted for full-rollout evidence.','2026-11-09','editorial',false from public.entities e where e.slug='saifuddin-nasution-ismail' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0005:mohamed-khaled-nordin:plkn-pilot-2025','Restart the PLKN 3.0 pilot in January 2025','Education','achieved',null,'2025-01-12','2024-12-16','https://bernama.com/bm/news.php?id=2374197','2025-02-04','https://www.bernama.com/bm/news.php?id=2389134','Mohamed Khaled announced a PLKN 3.0 trial starting on 12 January 2025, initially describing an intake of 200 participants.','His parliamentary update confirms the pilot began on 12 January with 120 trainees. Achieved covers the restart only: the originally announced 200-person intake is not marked fulfilled. Longer-term training outcomes and sole personal credit are not implied.','2026-11-09','editorial',false from public.entities e where e.slug='mohamed-khaled-nordin' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

